// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address sender, uint256 timeAdvance) public {
        vm.assume(sender != address(0));

        timeAdvance = bound(timeAdvance, 1, 1 days);

        vm.deal(sender, 20 ether);

        vm.warp(block.timestamp + timeAdvance);

        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        if (ok) {
            uint256 stored = c.pastBlockTime();
            assertTrue(stored == block.timestamp + 1);
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}
